static inline void bitmap_copy(unsigned long *dst, const unsigned long *src, /* <=== bitmap_copy */ 
			unsigned int nbits)
{
	if (small_const_nbits(nbits))
		*dst = *src;
	else {
		unsigned int len = BITS_TO_LONGS(nbits) * sizeof(unsigned long);
		memcpy(dst, src, len);
	}
}

